B.f1x=s(["close","missing"],t.s)
B.eE3=new A.dr("t5",B.df,"Your beginning","Tell each other about the moment you first knew you liked each other.","",B.f1x)
B.eDB=new A.dr("t6",B.df,"Something new","Plan one new thing to try together this month \u2014 a place, a dish, a walk you\u2019ve never taken.","",B.DK)
B.f1w=s(["close","calm"],t.s)
B.eDK=new A.dr("t7",B.df,"The ten-minute check-in","Spend ten minutes talking about your days \u2014 just listening and taking each other\u2019s side, no fixing.","",B.f1w)
B.eDH=new A.dr("t8",B.df,"Something ahead",'Ask: "What\u2019s something you\u2019re looking forward to?" and then ask one more question about it.',"",B.DK)
B.f_L=s(["admire","missing"],t.s)
