B.f9k=s(["new","team"],t.s)
B.eDk=new A.dr("t11",B.df,"Dream list","Write down three dreams each \u2014 for this year, for you two, for your life \u2014 and share them.","",B.f9k)
B.f1A=s(["close","steady"],t.s)
B.eDJ=new A.dr("t12",B.df,"Home",'Ask: "When do you feel most at home with me?"',"",B.f1A)
